def _diagnostic_ledger_segment_name(index: int) -> str:
    """Canonical file name of the segment with one-based ``index``."""
    return f"segment-{index:06d}.json"

@staticmethod
def _diagnostic_ledger_segment_index(name: Any) -> int | None:
    """The index encoded in a canonical segment file ``name``, or
    ``None`` when the name is malformed."""
    if not isinstance(name, str):
        return None
    if not name.startswith("segment-") or not name.endswith(".json"):
        return None
    digits = name[len("segment-") : -len(".json")]
    if len(digits) != 6 or not digits.isdigit():
        return None
    return int(digits)

@classmethod
def _diagnostic_ledger_evidence_name(cls, digest: str) -> str:
    """Content-addressed file name of the prefix evidence whose
    content has SHA-256 hex ``digest``. The full digest is used, so
    the name binds the exact content: a fresh rotation publishes a
    distinct name, the new evidence is in place before the manifest
    switch and the previous evidence only becomes garbage once that
    switch is durable."""

def _require_diagnostic_ledger_digest(cls, value: Any, what: str) -> str:
    """Require a 64-character lowercase hex digest field inside a
    manifest or segment; anything else raises :class:`ValueError`."""
    if (
        not isinstance(value, str)
        or len(value) != 64
        or set(value) - cls._HEX_DIGITS
    ):
        raise ValueError(f"{what} is malformed")
    return value

@classmethod
def _require_diagnostic_ledger_time(cls, value: Any, what: str) -> int:
    """Require a non-``bool`` non-negative :class:`int` time field
    inside a manifest; anything else raises :class:`ValueError`."""
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise ValueError(f"{what} is malformed")
    return value

@classmethod
def _diagnostic_ledger_segment_document(
    cls,
    index: int,
    prev: str,
    pairs: list[tuple[int, tuple[str, ...]]],
) -> bytes:
    """Serialize one immutable segment to its canonical bytes:
    compact UTF-8 JSON, no BOM, no trailing newline, with a SHA-256
    checksum over the canonical body. ``pairs`` must already be
    authenticated and sorted."""

"""Tests for the persistent diagnostic ledger.

``BranchStore.save_diagnostic_ledger`` seals a snapshot of
time-stamped recovery diagnostic chains into a compact, checksummed,
atomically replaced JSON ledger; ``BranchStore.page_diagnostic_ledger``
reads it back one snapshot-consistent page at a time through
resumption cursors that survive restarts.

These tests cover:

* ledger envelope shape: compact canonical UTF-8, no BOM, no trailing
  newline, SHA-256 checksum, entries stored in (time, transaction)
  order;
* argument validation for both entry points -- path, entries shape,
  entry times, chain authentication, time bounds, transaction filter,
  limit and cursor types;
* durable atomic replacement: failures raise ``OSError`` and leave a
  previous ledger byte-for-byte untouched;
* pagination: inclusive time bounds, transaction filtering (unknown
  identities never error, an empty tuple matches nothing), stable
  (time, transaction) ordering, multi-page iteration and the terminal
  ``None`` cursor;
* cursor semantics: cross-restart resume, filter binding, and
  ``RuntimeError`` when the ledger is replaced, truncated or appended
  to between pages;
* corrupt ledgers (encoding, checksum, structure or embedded chain
  authentication) raising ``ValueError`` with no partial page;
* strict read-only isolation of queries and fresh, unshared return
  levels.
"""

